import {mkdirSync,writeFileSync} from "node:fs";
import {randomUUID} from "node:crypto";
import {spawnSync} from "node:child_process";
const path=".www/evidence/dashboard-W024/product-off-"+randomUUID();
mkdirSync(path,{recursive:true,mode:0o700});
const argv=["scripts/test.ts"], now=new Date().toISOString();
const run=spawnSync(process.execPath,argv,{encoding:"utf8",env:{...process.env,BOXBOX_MODE:"off"},maxBuffer:12*1024*1024});
writeFileSync(path+"/stdout.log",run.stdout??"");
writeFileSync(path+"/stderr.log",run.stderr??"");
writeFileSync(path+"/process.json",JSON.stringify({kind:"process",command:process.execPath,argv,boxboxMode:"off",startedAt:now,exit:run.status,signal:run.signal,error:run.error?.message??null},null,2)+"\n");
console.log(JSON.stringify({path,exit:run.status,signal:run.signal}));
process.exit(run.status??1);

